import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../repositories/providers.dart';
class ExploreScreen extends ConsumerWidget{const ExploreScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final services=ref.watch(mockRepositoryProvider).services();final groups={'Money':['Expenses','Exchange Rates','Reminders'],'Shopping and Transport':['Prices','Fuel'],'Opportunities':['Jobs','Rentals'],'Community Services':['Outages'],'Knowledge':['Students','Farmers']};return Scaffold(appBar:AppBar(title:const Text('Explore')),body:ListView(padding:const EdgeInsets.all(16),children:[for(final g in groups.entries)...[SectionHeader(g.key),for(final s in services.where((x)=>g.value.contains(x.name))) ZayloCard(onTap:()=>context.push(s.route),child:ListTile(leading:Icon(IconData(s.icon,fontFamily:'MaterialIcons')),title:Text(s.name),subtitle:Text(s.description),trailing:const Icon(Icons.chevron_right)))] ]));}}
